-- Ensure role constraints and existing profile roles stay synchronized
UPDATE public.profiles SET role = 'customer' WHERE email = 'customer@aurashop.com';
UPDATE public.profiles SET role = 'staff'    WHERE email = 'staff@aurashop.com';
UPDATE public.profiles SET role = 'manager'  WHERE email = 'manager@aurashop.com';
UPDATE public.profiles SET role = 'admin'    WHERE email = 'admin@aurashop.com';